"Abstand Anfang / Ende":"Odstup začátek / konec",
"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Odstup začátku / konce udělá z příruby částečnou přírubu. Další uzavřené profily ve skice se stanou výřezy v desce. Díry a okna v přírubě: střed podél hrany (u zakřivené hrany podél oblouku), střed od konce ohybu, velikost – zobrazí se i v rozvinutém tvaru. Přechází-li zakřivená hrana bez zlomu do sousední hrany a mají-li obě přírubu se stejným úhlem ohybu, příruby do sebe přecházejí bez odlehčovacího výřezu. „Kontura ze skici“ vyřízne uzavřené profily skici z příruby: její X běží podél hrany, její Y do příruby, nulový bod leží na začátku hrany na konci ohybu (lze posunout).",
