"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Vyberte všechny plochy, které mají zmizet (u kapsy stěny a dno, u díry stěnu, u zaoblení zaoblení). Sousední plochy se přes mezeru prodlouží. Krok se při změnách tělesa přepočítává; poprvé se k tomu načítá velké geometrické jádro (několik sekund).",
