"Darstellungsqualität":"Kvalita zobrazení",
"Das Bild konnte nicht gelesen werden.":"Obrázek nelze přečíst.",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"Obrázek leží jako předloha na rovině. Velikost, polohu, natočení a krytí poté nastavte v okně vlastností (např. šířku podle známého rozměru).",
"Das Ergebnis des Geometriekerns ist unlesbar":"Výsledek geometrického jádra je nečitelný",
"Das Ergebnis konnte nicht geschrieben werden":"Výsledek se nepodařilo zapsat",
"Das Maß muss größer als 0 sein.":"Kóta musí být větší než 0.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"Síť zůstává trojúhelníkovou sítí (ne B-Rep). Úpravy v části SÍŤ: Opravit, Zredukovat, Vyhladit, Řez rovinou … 3D strategie frézování ve Výrobě ji mohou obrábět přímo.",
"Das Netz hat {0} Dreiecke. Jedes wird eine Fläche des Körpers – das dauert lange und macht den Körper träge. Vorher „Reduzieren“ ist meist besser.\n\nTrotzdem umwandeln?":"Síť má {0} trojúhelníků. Každý se stane plochou tělesa – trvá to dlouho a těleso bude pomalé. Předchozí „Zredukovat“ je obvykle lepší.\n\nPřesto převést?",
"Das Netz ist nicht geschlossen. Zuerst „Reparieren“ ausführen – ein Körper braucht eine geschlossene Hülle.":"Síť není uzavřená. Nejdříve proveďte „Opravit“ – těleso potřebuje uzavřený plášť.",
"Das Netz reicht in Z von {0} bis {1} mm, in X von {2} bis {3} mm, in Y von {4} bis {5} mm. Punkte, die weniger als die Toleranz von einer Geraden abweichen, entfallen.":"Síť sahá v Z od {0} do {1} mm, v X od {2} do {3} mm, v Y od {4} do {5} mm. Body, které se od přímky odchylují o méně než je tolerance, se vypustí.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"Profil nesmí protínat osu. Jako osa může sloužit otevřená čára ve skice.",
"Das Profil mit den jetzigen Werten überschreiben":"Přepsat profil aktuálními hodnotami",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"Profil se vede podél čáry nebo lomené čáry. Profil nejlépe kreslete kolmo k začátku dráhy (např. profil na XZ, dráha na XY).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"Profil se z roviny skici vyrazí vypouklý nebo vtlačený.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"Polotovar je kvádr kolem vybraného tělesa (plus přídavek).",
"Das Setup hat keine Operationen.":"Upnutí nemá žádné operace.",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"Nástroj frézuje v kruzích, jejichž střed putuje podél drážky. Není nikdy v záběru po celé šířce – to umožňuje velké hloubky řezu a šetří frézu i vřeteno. Fréza by měla mít asi 60 % šířky drážky.",
"Das Werkzeug schneidet die Fläche nicht":"Nástroj plochu neprotíná",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"Nástroj řeže směrem k vybraným plochám, dokud nedosáhne zadaných přídavků.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"Nástroj se zanořuje svisle jako vrták, řadu za řadou, až na model plus přídavek. Řezná síla působí podél vřetene: vhodné pro dlouhé nástroje, hluboké dutiny a méně tuhé stroje. Nástroj musí řezat přes střed.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"Nástroj se těmto plochám vyhýbá s ohledem na zadané bezpečnostní odstupy (upínky, svěrák).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"Nástroj se těmto plochám vyhýbá při obrábění okolních ploch a dodržuje bezpečnostní odstupy.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"První Esc zruší jen nástroj nebo výběr – přebytečný Esc skicu nezavře",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"Toto není díra (zaoblení nebo čep) – klikněte na vnitřní stěnu díry.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"Toto není díra (válcová plocha) – klikněte na stěnu díry.",
"Das ist keine WerkFab-Design-Datei.":"Toto není soubor vzhledu WerkFab.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"Toto není šikmá hrana – klikněte na oba konce hrany zkosení.",
"Datei":"Soubor",
"Datei ist keine WerkFab-Einstellungsdatei.":"Soubor není soubor nastavení WerkFab.",
"Datei konnte nicht geöffnet werden:":"Soubor se nepodařilo otevřít:",
"Dateiendung":"Přípona souboru",
