"Dateiname":"Název souboru",
"Daten und Speicher":"Data a úložiště",
"Datenpanel":"Datový panel",
"Datenpanel ein-/ausblenden":"Zobrazit/skrýt datový panel",
"Datenpanel öffnen…":"Otevřít datový panel…",
"Datum":"Datum",
"Datum/Uhrzeit":"Datum/čas",
"Deaktivieren":"Deaktivovat",
"Deckkraft":"Krytí",
"Deckkraft der Fenster":"Průhlednost oken",
"Der Durchmesser würde null oder negativ – Abstand verkleinern":"Průměr by byl nulový nebo záporný – zmenšete vzdálenost",
"Der Gewindefräser läuft im vollen Material: Den Zapfen vorher freifräsen (2D-Kontur außen um den Zapfen bis zur Gewindetiefe).":"Fréza na závity jede v plném materiálu: nejprve čep vyfrézujte (2D kontura vně kolem čepu až do hloubky závitu).",
"Der Körper hat auf dieser Ebene keinen Umriss.":"Těleso nemá na této rovině žádný obrys.",
"Der Körper wird mit den Dreiecken der Anzeige als Netz übernommen. Er selbst bleibt erhalten; spätere Änderungen am Körper ändern das Netz nicht.":"Těleso se převezme jako síť s trojúhelníky zobrazení. Samo zůstane zachováno; pozdější změny tělesa síť nezmění.",
"Der Körper wird um seine senkrechte Mittelachse abgetastet und als Halterkontur (Abschnitte) in der Dokument-Werkzeugbibliothek gespeichert.":"Těleso se nasnímá kolem své svislé středové osy a uloží jako kontura držáku (úseky) do knihovny nástrojů dokumentu.",
"Der Punkt, um den sich die Ansicht dreht (bei freiem Orbit). „Unter dem Mauszeiger“: die Stelle des Modells, an der die Drehung beginnt.":"Bod, kolem něhož se pohled otáčí (při volném orbitu). „Pod kurzorem myši“: místo na modelu, kde otáčení začíná.",
"Der Radius wächst gleichmäßig vom Anfang zum Ende jeder gewählten Kante. Welches Ende der Anfang ist, legt die Kante fest – bei Bedarf tauschen.":"Poloměr roste rovnoměrně od začátku ke konci každé vybrané hrany. Který konec je začátek, určuje hrana – v případě potřeby prohoďte.",
"Der Rand einer Fläche ist eine geschlossene Kette: Mit „durchlaufend“ läuft der Radius einmal ringsum, ohne diese Option auf jeder Kante für sich vom Anfangs- zum Endradius.":"Okraj plochy je uzavřený řetězec: s volbou „průběžně“ poloměr probíhá jednou dokola, bez této volby na každé hraně zvlášť od počátečního ke koncovému poloměru.",
"Der Schnitt trifft keinen Körper – es wird kein Material entfernt.":"Řez nezasahuje žádné těleso – neodebírá se žádný materiál.",
"Der Text steht als Kommentar an dieser Stelle im Programm.":"Text se v programu objeví jako komentář na tomto místě.",
"Der erste Abstand wird auf der Fläche gemessen, die mehr nach oben (Z) zeigt, der zweite Abstand bzw. der Winkel gilt zur anderen Fläche. „Seiten tauschen“ kehrt das um. Tangential anschließende Kanten laufen mit.":"První vzdálenost se měří na ploše, která směřuje více nahoru (Z), druhá vzdálenost nebo úhel platí k druhé ploše. „Prohodit strany“ to obrátí. Tečně navazující hrany se zahrnou.",
