"Die Abwicklung überlappt sich – so lässt sich das Teil nicht aus einem Blech schneiden. Laschen kürzen oder teilen.":"Rozvinutý tvar se překrývá – díl tak nelze vyřezat z jednoho plechu. Příruby zkraťte nebo rozdělte.",
"Die Ansicht folgt der Bewegung in die andere Richtung":"Pohled sleduje pohyb v opačném směru",
"Die Ansichten passen bei diesem Maßstab nicht auf das Blatt.":"Pohledy se v tomto měřítku na list nevejdou.",
"Die Bahnen haben überall denselben Abstand auf der Oberfläche – gemessen von der Leitkurve (ohne Skizze: vom Rand des Bearbeitungsbereichs).":"Dráhy mají na povrchu všude stejný odstup – měřeno od vodicí křivky (bez skici: od okraje obráběné oblasti).",
"Die Biegelinie liegt nicht in der Platte":"Ohybová čára neleží v desce",
"Die Bildebene wurde nicht getroffen – Ansicht drehen.":"Rovina obrázku nebyla zasažena – otočte pohled.",
