"Die Ebene berührt den Zylinder; der Winkel dreht die Berührlinie um die Zylinderachse, gemessen von der Bezugsebene.":"Rovina se dotýká válce; úhel otáčí dotykovou přímku kolem osy válce, měřeno od referenční roviny.",
"Die Ebene geht durch alle drei Punkte; Skizzen darauf wandern mit, wenn du die Punkte änderst.":"Rovina prochází všemi třemi body; skici na ní se přesunou spolu s ní, když body změníte.",
"Die Ebene schneidet das Netz nicht.":"Rovina síť neprotíná.",
"Die Ebene schneidet den Körper nicht":"Rovina těleso neprotíná",
"Die Fläche hat auf dieser Ebene keinen Rand (sie steht senkrecht dazu).":"Plocha nemá na této rovině žádný okraj (je k ní kolmá).",
"Die Fläche ist kleiner als der Bahnabstand":"Plocha je menší než boční přísuv",
"Die Fläche wird dort geteilt, wo das Werkzeug sie schneidet. Danach die Bereiche anklicken, die wegfallen sollen.":"Plocha se rozdělí tam, kde ji nástroj protíná. Poté klikněte na oblasti, které mají zmizet.",
"Die Fläche wird über die gewählten Randkanten hinaus tangential verlängert – auch an gebogenen Kanten.":"Plocha se za vybrané okrajové hrany tečně prodlouží – i u zakřivených hran.",
"Die Fläche wählen, die ersetzt werden soll":"Zvolte plochu, která se má nahradit",
"Die Form berührt den Körper nicht – im selben Körper entsteht ein loses Stück.":"Tvar se tělesa nedotýká – ve stejném tělese vznikne volný kus.",
"Die Kante steht senkrecht zur Skizzenebene – ihr Abbild ist nur ein Punkt.":"Hrana je kolmá k rovině skici – její průmět je jen bod.",
"Die Kanten müssen einen geschlossenen Rand bilden (z. B. die offene Öffnung eines Rohrs). Die neue Fläche spannt sich hinein – auch gewölbt. „Tangential“ lässt sie glatt an die Nachbarflächen anschließen.":"Hrany musí tvořit uzavřený okraj (např. otevřený konec trubky). Nová plocha se do něj napne – i zakřivená. „Tečně“ ji hladce napojí na sousední plochy.",
"Die Komponente bewegt sich relativ zu ihrem Bezug. Die Bewegungsstudie fährt den Bereich ab und prüft dabei auf Kollisionen.":"Komponenta se pohybuje vzhledem ke své referenci. Studie pohybu projde celý rozsah a kontroluje přitom kolize.",
