"Die Maschine hält an (M0), zum Beispiel zum Umspannen oder Späne entfernen. Die nächste Operation schaltet Spindel und Kühlmittel wieder ein. Der Text steht als Kommentar davor.":"Stroj se zastaví (M0), například pro přeupnutí nebo odstranění třísek. Další operace znovu zapne vřeteno a chlazení. Text je před ní jako komentář.",
