"Die NC-Prüfung rechnet für geschwenkte Setups (3+2) die Achswinkel nach, prüft die Achsgrenzen und ob Werkzeug, Halter oder Spindelnase in den Maschinentisch fahren.":"Kontrola NC u naklopených upnutí (3+2) přepočítá úhly os, zkontroluje limity os a zda nástroj, upínač nebo nos vřetena nenarazí do stolu stroje.",
"Die Nachbarflächen lassen sich nicht über die Lücke verlängern":"Sousední plochy nelze přes mezeru prodloužit",
