"Die Reihenfolge ist schon günstig: {0} Werkzeugwechsel, mehr lässt sich nicht sparen, ohne Operationen an derselben Stelle zu vertauschen.":"Pořadí je už příznivé: {0} výměn nástroje, víc se ušetřit nedá bez prohození operací na stejném místě.",
"Die Schnittkontur des Netzes mit einer Ebene als Skizze anlegen":"Vytvořit skicu z kontury řezu sítě rovinou",
"Die Schnittlage liegt außerhalb des Teils – der Schnitt wird nicht gezeichnet.":"Poloha řezu leží mimo součást – řez se nevykreslí.",
"Die Seitenwände neigen sich um diesen Winkel. Positiv: der Körper wird von der Skizze weg breiter, negativ: schmaler (Entformungsschräge).":"Boční stěny se o tento úhel naklánějí. Kladný: těleso se směrem od skici rozšiřuje, záporný: zužuje (úkos pro vyjmutí z formy).",
"Die Skizze beschreibt die Schneidkante: X = Radius, Y = Höhe über der Spitze (die Y-Achse ist die Werkzeugachse). Gespiegelte Hälften werden zusammengefasst.":"Skica popisuje řeznou hranu: X = poloměr, Y = výška nad špičkou (osa Y je osa nástroje). Zrcadlené poloviny se spojí.",
"Die Skizze der Tasche muss längs zur Drehachse liegen (sie wird auf den Umfang gewickelt) – für die Stirnseite „Tasche Planfläche“":"Skica kapsy musí ležet podél osy otáčení (navine se na obvod) – pro čelo použijte „Kapsa na čelní ploše“",
"Die Skizze der Tasche muss quer zur Drehachse liegen (auf der Planfläche)":"Skica kapsy musí ležet kolmo na osu rotace (na čelní ploše)",
