"Die Skizze muss quer zur Drehachse (Planfläche) oder längs zu ihr (zum Abwickeln) liegen":"Skica musí ležet kolmo na osu otáčení (čelní plocha) nebo podél ní (pro rozvinutí)",
"Die Skizze muss quer zur Drehachse liegen (auf der Planfläche) – für den Umfang „Kontur Mantelfläche“":"Skica musí ležet kolmo na osu rotace (na čelní ploše) – pro obvod použijte „Kontura na plášti“",
"Die Skizzenebene muss parallel zur Zylinderachse liegen (z. B. eine Tangentialebene).":"Rovina skici musí být rovnoběžná s osou válce (např. tečná rovina).",
"Die Skizzenebene schneidet diesen Körper nicht.":"Rovina skici toto těleso neprotíná.",
