"Die fertige Bahn wird an den weiteren Stellen wiederholt (Maße ab Werkstück-Nullpunkt). Das Modell und das Rohteil müssen dort Material haben – die Simulation zeigt es.{0}":"Hotová dráha se opakuje na dalších místech (rozměry od nulového bodu obrobku). Model a polotovar tam musí mít materiál – ukáže to simulace.{0}",
"Die gespiegelte Form berührt den Körper nicht – es entsteht ein loses Stück.":"Zrcadlený tvar se tělesa nedotýká – vznikne volný kus.",
"Die gewählte ebene Fläche wird durch die Zielebene ersetzt: Der Körper wächst bis zu ihr oder wird bis zu ihr gekürzt, die Seitenwände laufen gerade weiter. Mit einer geneigten Konstruktionsebene wird die Fläche schräg.":"Vybraná rovinná plocha se nahradí cílovou rovinou: těleso k ní naroste nebo se k ní zkrátí, boční stěny pokračují přímo. S nakloněnou konstrukční rovinou se plocha stane šikmou.",
"Die gewählten Flächen bekommen eine Dicke entlang ihrer Normalen – auch gewölbte Flächen. Angrenzende Flächen werden zu einem Stück verbunden.":"Vybrané plochy získají tloušťku ve směru svých normál – i zakřivené plochy. Přilehlé plochy se spojí v jeden kus.",
