"Durchzug":"Límec",
"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}) – der Rand reißt dabei meist ein.":"Límec {0}: předvrtaný otvor Ø {1} mm se rozšíří na Ø {2} mm (faktor {3}) – okraj přitom většinou praskne.",
"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}).":"Límec {0}: předvrtaný otvor Ø {1} mm se rozšíří na Ø {2} mm (faktor {3}).",
"Durchzug {0}: liegt {1} mm neben dem Rand (weniger als 2 × Blechdicke) – der Rand beult aus.":"Límec {0}: leží {1} mm od okraje (méně než 2 × tloušťka plechu) – okraj se vyboulí.",
"Durchzug {0}: zu hoch für diese Bohrung (die Vorbohrung bliebe ohne Durchmesser)":"Límec {0}: příliš vysoký pro tuto díru (předvrtanému otvoru by nezůstal žádný průměr)",
"Durchzug: der Rand einer runden Bohrung wird zu einem Kragen hochgezogen, etwa als Gewindedurchzug. Der Bohrungsdurchmesser der Skizze ist der fertige Innendurchmesser; im Zuschnitt wird die kleinere Vorbohrung geschnitten.":"Límec: okraj kulaté díry se vytáhne do límce, například jako vytažená díra pro závit. Průměr díry ve skice je hotový vnitřní průměr; v přířezu se vyřízne menší předvrtaný otvor.",
