"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"Vlastní zkratky: na panelu nástrojů otevřete nabídku skupiny (▾), u příkazu klikněte na ⋮ → „Změnit klávesovou zkratku …“.",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Vlastní kóty a poznámky lze na listu přetahovat myší (vzdálenost kótovací čáry, úhel odkazové čáry, poloměr úhlového oblouku). Dva rohy = délková kóta. Okraj kružnice v pohledu shora = průměr (resp. poloměr). Úhel: nejprve vrchol, potom po jednom bodu na obou ramenech. Zkosení: oba konce šikmé hrany – vyjde např. 2×45°. V textovém poli za každou kótou je dodatek jako ±0,1, H7 nebo 4×.",
