"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Kulatá fréza nechává v každém vnitřním rohu svůj poloměr – hranatý protikus do něj pak nezapadne. Odlehčení krátce zajede do rohu a zpět v každém ostrém vnitřním rohu.{0}{1}",
