"Erhebung braucht zwei Skizzen mit geschlossenen Profilen auf verschiedenen Ebenen.":"Loft vyžaduje dvě skici s uzavřenými profily na různých rovinách.",
"Erhebung braucht zwei Skizzen mit je einer Kurve (auf verschiedenen Ebenen).":"Loft vyžaduje dvě skici, každou s jednou křivkou (na různých rovinách).",
"Erhebung nicht möglich – Querschnitte prüfen (je ein geschlossenes Profil, nicht verdreht)":"Loft není možný – zkontrolujte průřezy (vždy jeden uzavřený profil, nezkroucený)",
