"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Nejprve klikněte na plochu na tělese, které se přesouvá, poté na cílovou plochu na druhém tělese. Těleso se otáčí a posouvá, dokud první bod kliknutí neleží na druhém a plochy na sobě nelehnou.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Nejprve klikněte na hranu na tělese, které se přesouvá, poté na cílovou hranu na druhém tělese. Rovné hrany se položí do shody (střed na střed); u kruhových hran – díra a čep – se osy srovnají a středy se spojí.",
"Erst ein Setup anlegen.":"Nejprve vytvořte upnutí.",
"Erst ein Setup mit Operationen anlegen.":"Nejprve vytvořte upnutí s operacemi.",
"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Nejprve vyberte skicu nebo konstrukční rovinu – Ctrl+8 pak zobrazí pohled kolmo na ni.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Nejprve vytvořte těleso v KONSTRUKCI nebo vložte síť (STL).",
"Erst einen Körper in KONSTRUKTION erstellen.":"Nejprve vytvořte těleso v KONSTRUKCI.",
"Erst einen Namen für das Profil eingeben.":"Nejprve zadejte název profilu.",
"Erst in eine Vorlage klicken, dann den Platzhalter wählen":"Nejprve klikněte do šablony, poté vyberte zástupný symbol",
"Erste Ecke klicken, dann gegenüberliegende Ecke.":"Klikněte na první roh, poté na protilehlý roh.",
"Erstellen":"Vytvořit",
"Erstellt {0}":"Vytvořeno {0}",
"Ersten Bogenmittelpunkt, zweiten Bogenmittelpunkt, dann Breite klicken.":"Klikněte na první střed oblouku, druhý střed oblouku a poté na šířku.",
"Ersten Punkt gewählt – jetzt den zweiten anklicken.":"První bod vybrán – nyní klikněte na druhý.",
"Erster Werkzeugaufruf":"První vyvolání nástroje",
"Erzeugen":"Vytvořit",
