"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Plochy na konci dílu (dvouhran, čtyřhran, šestihran) poháněnou stopkovou frézou po Z. Rozevření klíče = dvojnásobná vzdálenost plochy od osy otáčení. X a C jedou společně (polární interpolace, Fanuc G12.1); bez této šablony v postprocesoru se vydávají krátké kroky X/C.",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"Klikejte na plochy, které se mají ztloušťovat (opětovným kliknutím se odeberou).",
