"Fusion-360-Dateien (.f3d) sind ein geschlossenes Autodesk-Format und können nicht gelesen werden.\n\nIn Fusion 360: Datei → Exportieren → STEP (.stp) wählen und diese Datei hier importieren.":"Soubory Fusion 360 (.f3d) jsou uzavřený formát Autodesk a nelze je číst.\n\nVe Fusion 360 zvolte: Soubor → Exportovat → STEP (.stp) a tento soubor zde importujte.",
