"Fährt alle scharfen Außenkanten ab, die von oben erreichbar sind, und bricht sie um die Entgrattiefe – mit dem Fasenfräser als Fase (Werkzeugachse senkrecht, Spitze außerhalb der Kante), mit dem Kugel-/Lollipop-Fräser gerundet.":"Projede všechny ostré vnější hrany dosažitelné shora a zlomí je o hloubku odhrotování – frézou na zkosení jako zkosení (osa nástroje svisle, špička mimo hranu), kulovou/lollipop frézou zaoblením.",
