"Für Touchpads: Scrollen verschiebt die Ansicht, Auseinanderziehen (oder Strg + Mausrad) zoomt":"Pro touchpady: posouvání posouvá pohled, roztažení prstů (nebo Ctrl + kolečko) zoomuje",
