"Für schräge Richtungen eine Konstruktionsachse anlegen (durch zwei Punkte, einen Zylinder oder zwei Ebenen) – sie erscheint dann hier als Richtung.":"Pro šikmé směry vytvořte konstrukční osu (dvěma body, válcem nebo dvěma rovinami) – zobrazí se zde jako směr.",
