"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Rovné čáry skici, které nepatří k žádnému profilu (i pomocné čáry). Ohyb: čára je střed ohybové zóny a skica je tam přířezem – největší kus desky zůstane na místě, vše za čárou se otočí i se svými přírubami. Čára platí přes celou desku. Prolis: žebro podél čáry, v průřezu i na koncích zaoblené; plech si zachová tloušťku.",
