"Gesamte Rechenzeit":"Celková doba výpočtu",
"Gesamtes axiales Rohteilaufmaß":"Celkový axiální přídavek polotovaru",
"Gesamtes radiales Rohteilaufmaß":"Celkový radiální přídavek polotovaru",
