"Geschlossen":"Uzavřeno",
"Geschlossen (Gehrung)":"Uzavřené (pokos)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Uzavřené: příruby na dvou sousedních hranách vedou až k ose úhlu rohu a nechávají tam mezeru. Odlehčení rohu leží tam, kde se ohybové zóny kříží – v rozvinutí i v ohnutém dílu. I příruba na zakřivené hraně se na skutečném rohu řeže na pokos (bez odlehčení rohu).",
"Geschlossene Kette {0}":"Uzavřený řetězec {0}",
"Geschlossene Profile begrenzen den Bereich.":"Oblast ohraničují uzavřené profily.",
"Geschlossene Profile der aktiven Skizze farbig füllen":"Barevně vyplnit uzavřené profily aktivní skici",
"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"Uzavřené profily se stanou rovinnými plochami – např. víko a dno, aby se plochy poté sešily do tělesa.",
"Geschnitten ab X":"Řez od X",
