"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"Importovaná tělesa nemají historii konstrukce, lze je však dále upravovat (zaoblení, zkosení, vyříznutí …) a použít pro CAM. Volbou „Osa Y nahoře“ se modely z programů s osou Y nahoru postaví správně.",
