"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"Z každé skici první křivka – otevřená nebo uzavřená. Křivky se spojí povrchem (plocha bez tloušťky).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Einschalten mit M3 (Laser: M3 S…), Ausschalten mit M5, Einstechzeit als G4. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Jeden tabuli jeden soubor. Dráha vede o polovinu řezné spáry (při frézování o polovinu frézy) vedle obrysu v odpadu; výřezy jdou před obrysem svého dílu, každá kontura začíná nájezdem z odpadu. Zapnutí M3 (laser: M3 S…), vypnutí M5, doba propíchnutí jako G4. Nulový bod je levý dolní roh tabule, při frézování je Z0 horní strana plechu. Program před nasazením na stroji nebo v NC simulátoru zkontrolujte.",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Každá osa zvlášť: klikněte na hranu, roh, plochu nebo díru. Nenastavené osy se převezmou z bodu polotovaru.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Každá operace jako podprogram (LBL) na konci programu, volání pomocí CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Každá kružnice skici je střed díry. Vrtá se proti normále skici (do materiálu).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Každá kružnice skici se opakuje otočená kolem středu (v souřadnicích skici) – kružnice ve vzdálenosti poloměru roztečné kružnice dává kruh děr.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Každá kružnice skici se stane mřížkou: rozteče v X a Y skici (i záporné).",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Nyní bod na druhém rameni.",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"Nyní každý směr jednou až na doraz: posun, tah, tlak, naklopení, otočení (10 s) …",
