"Kontur mit {0} Punkten – Okuma: G85 (LAP) mit Kontur G81…G80, Fanuc: G71 P…Q…. Die Steuerung schruppt mit ihrer eigenen Aufteilung; die Simulation hier ist die WerkFab-Bahn.":"Kontura s {0} body – Okuma: G85 (LAP) s konturou G81…G80, Fanuc: G71 P…Q…. Řídicí systém hrubuje s vlastním rozdělením řezů; simulace zde je dráha WerkFab.",
