"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Kontury sledují okraj tmavých ploch. Osa tahů vede středem tahů – vhodné pro gravírování a čárové kresby. „Přímky, oblouky a kružnice“ rozpozná rovné hrany, ostré rohy, zaoblení a kružnice; „Lomené čáry“ sledují obrázek bod po bodu. Měřítko pak podle potřeby upravte pomocí „Kalibrovat předlohu“ nebo „Měnit měřítko“.",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"Kontury s korekcí poloměru v řídicím systému (RL/RR) se najíždějí a vyjíždějí pomocí APPR/DEP; řídicí systém si pomocný bod a korekci vypočítá sám",
