"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Křivky skici na čele (napříč osou otáčení) poháněnou frézou po Z (X a C jedou společně; Fanuc: polární interpolace G12.1). Otevřené křivky se frézují tam a zpět. Hloubka od čela.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Křivky skici ležící podél osy otáčení se navinou na obvod a frézují poháněnou frézou směřující k ose (Z a C jedou společně; Fanuc: válcová interpolace G7.1). Rovina skici určuje úhel, ve kterém kontura leží; vodorovné úsečky ve skice se stanou oblouky kolem dílu. Hloubka od vnějšího průměru.",
"Kurzbefehl":"Zkratka",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Krátké cesty (do vzdálenosti držení) nástroj ujede dole přechodovým posuvem místo přes výšku stažení – bez kontroly kolizí, proto ji držte malou.",
