"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Několik navazujících hran se počítá jako jedna dráha: poloměr probíhá od začátku řetězce do jeho konce, řídicí body platí v % celé délky řetězce. Počítá to velké geometrické jádro.",
