"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"S řídicími body probíhá poloměr zadanými hodnotami (poloha v % délky hrany). Počítá to velké geometrické jádro; poprvé se načítá několik sekund.",
"Mit dem 3D-Taster kann nicht zerspant werden":"3D sondou nelze obrábět",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Porovnat s hotovým dílem: zelená = na míru, modrá = zbylý materiál, červená = příliš hluboko",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Najeďte myší vedle kontury (strana určuje směr) · Esc ukončí",
"Mit diesem Werkzeug kann nicht gefräst werden":"Tímto nástrojem nelze frézovat",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"Se závitníkem použijte jen cyklus „Řezání závitů“ – vrtací cyklus by jej zlomil",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"Při více přísuvech se hloubka závitu frézuje v krocích, z nichž každý ubírá přibližně stejně – šetří malé frézy na závity a tvrdé materiály. Průchod naprázdno projede poslední dráhu ještě jednou bez přísuvu.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"S volbou „Vrtací cykly“ v NC programu se vydávají cykly řídicího systému (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), jinak rozepsané pohyby.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"S volbou „Ponechat originál“ se originál a zrcadlový obraz stanou jednou sítí; body na rovině zrcadlení se spojí – z otevřené poloviny tak vznikne uzavřený díl.",
