"Nur Außenkonturen (Zapfen) gehen als Steuerungszyklus":"Jako cyklus řídicího systému lze zadat jen vnější kontury (čepy)",
"Nur Durchmesser (Form wie dieses Werkzeug)":"Jen průměr (tvar jako tento nástroj)",
"Nur Innenkonturen (Öffnungen)":"Jen vnitřní kontury (otvory)",
"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"Jako cyklus řídicího systému lze zadat jen obdélníkové a kruhové kapsy",
"Nur Skizze":"Pouze skica",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Obrobit jen to, co větší fréza v rozích nechala.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Obrobit jen místa kontury, kam větší fréza nedosáhla (vnitřní rohy, úzká místa). Bez najížděcích/odjížděcích oblouků, můstků a dokončovacích průchodů; korekce v počítači.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Jen tam, kam referenční nástroj nedosáhl: ploché oblasti paralelně, strmé oblasti jako vrstevnice. S nástrojem ze seznamu se počítá i jeho tvar – například to, co torusová fréza nechá v žlábcích.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Jako rovina skici lze použít jen rovinné plochy.",
"Nur ebene Flächen können extrudiert werden":"Vysunout lze pouze rovinné plochy",
"Nur ebene Flächen lassen sich ersetzen":"Nahradit lze pouze rovinné plochy",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Odsadit lze pouze rovinné a válcové plochy (díry, čepy)",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Pouze rovinné plochy směřující vzhůru k nástroji (vodorovné v tomto upnutí).",
"Nur für Außen-Drehmeißel":"Jen pro vnější soustružnické nože",
"Nur in Operationen verwendete":"Pouze použité v operacích",
"Nur in diesem Projekt":"Pouze v tomto projektu",
"Nur mit Korrektur „Im Rechner“.":"Jen s korekcí „V počítači“.",
"Nur stärkste Achse":"Pouze dominantní osa",
"Nut":"Drážka",
"Nut angetrieben":"Drážka poháněným nástrojem",
"Nut angetrieben (C-Achse)":"Drážka poháněným nástrojem (osa C)",
"Nut liegt nicht am Teil":"Drážka neleží na dílu",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Drážka podél osy otáčení (např. drážka pro pero) poháněnou frézou směřující k ose; hlavní vřeteno drží díl jako osu C. Šířka drážky = Ø frézy. Začátek/konec Z v Z modelu; sahá-li drážka k čelu, fréza najíždí zepředu, jinak se zanořuje na začátku. Hloubka od vnějšího průměru.",
