"Offene Flächen":"Otevřené plochy",
"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"Otevřené hrany se zobrazují červeně. „Opravit“ uzavře otvory.",
"Offene Linie in einer Skizze wählen":"Zvolte otevřenou čáru ve skice",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Otevřené nebo uzavřené křivky se vytáhnou kolmo ke skice – vznikne plocha (stěna bez tloušťky). Pomocí „Zesílit“ nebo „Sešít“ z ní vznikne objem.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Otevřené nebo uzavřené křivky se otáčejí kolem osy – vznikne plocha, nikoli objem.",
"Ohne eigene Taste gilt der Standard „{0}“.":"Bez vlastní klávesy platí výchozí „{0}“.",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"Bez volby „Modelovaný“ se závit jen zobrazí (rychle). Při modelování se tvar závitu skutečně vyřízne, např. pro 3D tisk. Díra pro M8 = Ø6,8.",
"Okuma OSP Drehen":"Okuma OSP soustružení",
"Okuma OSP-M Fräsen":"Okuma OSP-M frézování",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: G28/G53 zde nenajíždějí na souřadnice stroje (G53 ruší korekci délky nástroje) – odjezd na bezpečnou výšku, referenční jízda v XY nebyla vypsána",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: funkce vyhlazení nebyla vypsána (G5.1 je Fanuc) – nastavte Hi-Cut/Super-NURBS na stroji",
"Okuma: Korrektur+Werkzeug+Schneide (z. B. 010101)":"Okuma: korekce+nástroj+ostří (např. 010101)",
"OpenCascade (alle Funktionen)":"OpenCascade (všechny funkce)",
"OpenCascade: alle Funktionen. Rust-Kern (truck, experimentell): Grundkörper, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren, Kombinieren und STEP-Export – andere Features werden als „noch nicht unterstützt“ markiert.":"OpenCascade: všechny funkce. Jádro Rust (truck, experimentální): základní tělesa, vysunutí, rotace, díra, pole, zrcadlení, přesun, měřítko, kombinace a export STEP – ostatní prvky jsou označeny jako „zatím nepodporováno“.",
