"Projizieren (J): Fläche oder Kante eines Körpers anklicken – ihr Abbild kommt in die Skizze":"Promítnout (J): klikněte na plochu nebo hranu tělesa – její průmět se přidá do skici",
"Projizieren von Kanten und Flächen braucht einen Volumenkörper des Standardkerns – Körperumriss und Schnittkurven gehen auch bei Netzen.":"Promítnutí hran a ploch vyžaduje objemové těleso standardního jádra – obrys tělesa a průsečné křivky fungují i u sítí.",
