"Prägung {0}: die Kontur ist schmaler als 2 × Blechdicke – es bleibt kein Hohlraum.":"Vytlačení {0}: kontura je užší než 2 × tloušťka plechu – nezůstane žádná dutina.",
"Prägung {0}: lässt sich so nicht formen":"Vytlačení {0}: takto nelze vytvarovat",
"Prägung {0}: {1} mm ist höher als 3 × Blechdicke – mit senkrechter Wand reißt das Blech.":"Vytlačení {0}: {1} mm je více než 3 × tloušťka plechu – se svislou stěnou plech praskne.",
"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt. Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"Vytlačení: kontura se nevyřízne, ale vytlačí se o danou výšku z desky. Lisované zahloubení: okraj kulaté díry se vtlačí do 90° kužele – pro zápustné šrouby v tenkém plechu (− dolů: šroub shora).",
