"Tasche Planfläche (C-Achse)":"Kapsa na čelní ploše (osa C)",
"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Kapsa na obvodu z uzavřených kontur skici, která leží podél osy otáčení (vnitřní kontury zůstanou jako ostrůvky). Skica se navine na průměr; poháněná stopková fréza směřující k ose vybírá zevnitř ven (Z a C se pohybují společně; Fanuc: válcová interpolace G7.1). Fréza zajíždí po rampě podél nejvnitřnějšího prstence.",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Kapsa v čele z uzavřených kontur skici (vnitřní kontury zůstanou jako ostrůvky) poháněnou stopkovou frézou po Z. Vybírá se zevnitř ven; fréza se zanořuje po rampě podél nejvnitřnější dráhy a v rámci jedné roviny zůstává dole. X a C jedou společně (Fanuc: polární interpolace G12.1). Hloubka od čela.",
"Tasche mit Insel – der Steuerungszyklus kann keine Inseln":"Kapsa s ostrůvkem – cyklus řídicího systému ostrůvky nezvládá",
"Tasche schmaler als das Werkzeug":"Kapsa je užší než nástroj",
