"Vernetzung fehlgeschlagen:":"Vytvoření sítě selhalo:",
"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Skutečně vzájemně spočítá dvě uzavřené sítě: vnitřní plochy zmizí, hrany řezu se znovu vysíťují. Počítá se jen tam, kde se obě sítě mohou setkat – velká síť s malým zásahem proto jde rychle. Pokud se dvě velké sítě překrývají celé, nejdřív „Zredukovat“.",
