"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Navine křivky skici na válec: X zůstává X, vzdálenost napříč osou se stane obloukem na Ø navinutí (otáčení A). Skica musí ležet rovnoběžně s osou A, např. na tečné rovině. Frézuje se v pevné hloubce pod povrchem dílu – pro gravírování, nápisy a drážky kolem dílu.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"Jako 3D kontura, ale nástroj klesá plynule bez stupňů – žádné stopy po zanoření na strmých stěnách.",
