"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"„Do sebe zasunout“ uloží přířezy do mezer a zálivů sousedních dílů i do jejich výřezů (bez otáčení o 90° jen převrácené o 180°); odstup se nikdy nepodkročí. Bez zaškrtnutí leží v řadách podle svého opsaného obdélníku. S volbou „Skica + tělesa“ vzniknou plochá tělesa o tloušťce plechu, která lze ve výrobě vyříznout pomocí 2D kontury.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"„Uvnitř/Vně“ vyžaduje uzavřené kontury – otevřené křivky frézujte volbou „Na křivce“",
