"⚠ Programmlogik (JavaScript) wird nicht ausgeführt: Sonderfunktionen, 4./5. Achse, Messzyklen und Maschinenoptionen bitte im Postprozessor-Editor prüfen.":"⚠ Programová logika (JavaScript) se nespouští: zvláštní funkce, 4./5. osu, měřicí cykly a volby stroje zkontrolujte v editoru postprocesoru.",
